{
  "title": "functions.expression.IntegerInputSchema",
  "description": "Schema for an integer input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the integer.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "maximum": {
      "description": "Maximum allowed value (inclusive).",
      "anyOf": [
        {
          "type": "integer",
          "minimum": -9223372036854775808,
          "maximum": 9223372036854775807
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "minimum": {
      "description": "Minimum allowed value (inclusive).",
      "anyOf": [
        {
          "type": "integer",
          "minimum": -9223372036854775808,
          "maximum": 9223372036854775807
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.IntegerInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.AnyOfInputSchema",
  "description": "Schema for a union of possible types - input must match at least one.",
  "type": "object",
  "properties": {
    "anyOf": {
      "description": "The possible schemas that the input can match.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputSchema"
      }
    }
  }
}

{
  "title": "functions.expression.ImageInputSchema",
  "description": "Schema for an image input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected image.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ImageInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.InputValue",
  "description": "A concrete input value (post-compilation).\n\nRepresents any JSON-like value that can be passed to a Function,\nincluding rich content types (images, audio, video, files).",
  "anyOf": [
    {
      "title": "RichContentPart",
      "description": "Rich content (image, audio, video, file).",
      "$ref": "agent.completions.message.RichContentPart"
    },
    {
      "title": "Object",
      "description": "An object with string keys.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputValue"
      }
    },
    {
      "title": "Array",
      "description": "An array of values.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputValue"
      }
    },
    {
      "title": "String",
      "description": "A string value.",
      "type": "string"
    },
    {
      "title": "Integer",
      "description": "An integer value.",
      "type": "integer",
      "minimum": -9223372036854775808,
      "maximum": 9223372036854775807
    },
    {
      "title": "Number",
      "description": "A floating-point number.",
      "type": "number",
      "minimum": -3.4028234663852886e+38,
      "maximum": 3.4028234663852886e+38
    },
    {
      "title": "Boolean",
      "description": "A boolean value.",
      "type": "boolean"
    }
  ]
}

{
  "title": "agent.completions.message.RichContentPart",
  "description": "A part of rich content.",
  "anyOf": [
    {
      "title": "Text",
      "description": "Text content.",
      "type": "object",
      "properties": {
        "text": {
          "type": "string"
        },
        "type": {
          "type": "string",
          "enum": [
            "text"
          ]
        }
      }
    },
    {
      "title": "ImageUrl",
      "description": "An image URL.",
      "type": "object",
      "properties": {
        "image_url": {
          "$ref": "agent.completions.message.ImageUrl"
        },
        "type": {
          "type": "string",
          "enum": [
            "image_url"
          ]
        }
      }
    },
    {
      "title": "InputAudio",
      "description": "Audio input.",
      "type": "object",
      "properties": {
        "input_audio": {
          "$ref": "agent.completions.message.InputAudio"
        },
        "type": {
          "type": "string",
          "enum": [
            "input_audio"
          ]
        }
      }
    },
    {
      "title": "InputVideo",
      "description": "Video input.",
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "input_video"
          ]
        },
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        }
      }
    },
    {
      "title": "VideoUrl",
      "description": "A video URL.",
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "video_url"
          ]
        },
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        }
      }
    },
    {
      "title": "File",
      "description": "A file.",
      "type": "object",
      "properties": {
        "file": {
          "$ref": "agent.completions.message.File"
        },
        "type": {
          "type": "string",
          "enum": [
            "file"
          ]
        }
      }
    }
  ]
}

{
  "title": "functions.expression.AudioInputSchema",
  "description": "Schema for an audio input.",
  "type": "object",
